INSERT INTO calendars (title, category, description, icon, tier_required, status) VALUES ('Mindfulness & Self-Help', 'Mindfulness/Self-Help', '24 small daily wellbeing activities for calm, focus and kindness to yourself.', 'ph-flower-lotus', 'free', 'active');
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'The 3-Breath Anchor', 'Slow exhalations activate the parasympathetic nervous system, immediately lowering heart rate and cortisol.', 'Pause everything you are doing. Take three slow, deliberate breaths: inhale for 4 seconds, hold for 4 seconds, and exhale softly for 6 seconds. Notice your shoulders dropping.', 1, 20, '2 mins', 'ph-wind', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Gratitude Spotlight', 'Specificity trains your brain''s reticular activating system to scan for positive moments throughout the day.', 'Write down 3 ultra-specific things that went well in the last 24 hours. Instead of ''my friends'', write ''the funny voice note Sarah sent me this morning''.', 2, 20, '5 mins', 'ph-sun-horizon', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Digital Sunset', 'Reducing constant dopamine micro-hits restores baseline focus and improves sleep quality.', 'Put your phone in another room or on Airplane Mode for the next 15 minutes (or 30 minutes before bed tonight). Use the quiet space to stretch or daydream.', 3, 20, '15 mins', 'ph-moon-stars', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'The 2-Minute Tidy', 'External order reduces visual cognitive load, freeing up working memory in your brain.', 'Pick one small surface near you—your desk corner, nightstand, or backpack. Set a 2-minute timer and clear away any clutter or trash.', 4, 20, '2 mins', 'ph-broom', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Unsent Appreciation Text', 'Expressing warmth boosts oxytocin for both the sender and receiver while removing social pressure.', 'Message someone you haven''t spoken to in a while just to tell them one thing you appreciate about them—with ''no need to reply!'' at the end.', 5, 20, '3 mins', 'ph-chat-circle-heart', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), '5-4-3-2-1 Sensory Grounding', 'Sensory grounding interrupts anxious rumination by pulling attention back into the physical present.', 'Name 5 things you can see, 4 things you can physically feel, 3 things you can hear, 2 things you can smell, and 1 thing you appreciate about yourself right now.', 6, 20, '4 mins', 'ph-hand-palm', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Hydration & Posture Check', 'Mild dehydration often masquerades as fatigue or irritability.', 'Drink a full glass of water slowly. As you drink, unclench your jaw, drop your tongue from the roof of your mouth, and roll your shoulders back.', 7, 20, '2 mins', 'ph-drop', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Single-Tasking Sprint', 'Overcoming activation energy is the hardest part of any task; starting shrinks perceived difficulty.', 'Pick one small task you''ve been procrastinating on. Close all other browser tabs and work on ONLY that task for 10 minutes. Permission to stop when the timer ends!', 8, 30, '10 mins', 'ph-target', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Self-Compassion Reframe', 'Self-compassion builds emotional resilience far more effectively than harsh self-criticism.', 'Identify one thing you criticized yourself for recently. Rewrite that thought as if you were speaking to a dear friend in the exact same situation.', 9, 20, '5 mins', 'ph-heart-half', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Music Mood Shift', 'Active music listening engages wide neural networks involved in emotion regulation.', 'Put on one song that makes you feel nostalgic, energized, or peaceful. Do nothing else while it plays—just listen to the instruments and rhythm.', 10, 20, '4 mins', 'ph-music-notes', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Micro-Walk Without Audio', 'Unstructured quiet time activates the brain''s Default Mode Network, sparking creative problem-solving.', 'Step outside for a 10-minute walk without headphones or podcasts. Let your thoughts wander freely and observe the sky, trees, or architecture.', 11, 20, '10 mins', 'ph-footprints', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Brain Dump List', 'Externalizing thoughts stops the Zeigarnik effect—your brain''s tendency to loop on unfinished tasks.', 'Grab a piece of paper and write down every unfinished task, worry, or reminder floating in your head. Circle just ONE thing to care about today.', 12, 20, '5 mins', 'ph-notebook', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Compliment a Stranger or Peer', 'Micro-moments of positivity resonance strengthen our sense of community belonging.', 'Give one genuine compliment today—to a barista, a coworker, or a classmate. Notice how their expression shifts.', 13, 20, '2 mins', 'ph-smiley', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Box Breathing Reset', 'Used by first responders to regain calm and cognitive control under high stress.', 'Visualize a square. Inhale for 4 counts up the left side, hold for 4 across the top, exhale for 4 down the right, and hold for 4 across the bottom. Repeat 4 times.', 14, 20, '3 mins', 'ph-square', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Curate Your Feed', 'Protecting your attentional diet prevents passive social comparison.', 'Open your most-used social app and mute or unfollow 3 accounts that consistently make you feel inadequate, drained, or unnecessarily angry.', 15, 20, '5 mins', 'ph-scissors', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Savoring Ritual', 'Savoring extends the duration of positive emotions and anchors you in the present.', 'During your next cup of tea, coffee, or snack, eat or drink the first three sips/bites at half speed. Notice the temperature, aroma, and texture.', 16, 30, '5 mins', 'ph-coffee', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Done List (Instead of To-Do)', 'Celebrating small wins builds self-efficacy and momentum.', 'Write down 5 things you have already accomplished this week—even small wins like answering an email, cooking a meal, or showing up on a tough day.', 17, 20, '4 mins', 'ph-list-checks', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Neck & Eye Release', 'Relieves ocular strain and trapezius tension caused by screen posture.', 'Follow the 20-20-20 rule: look at something 20 feet away for 20 seconds, then gently tilt your right ear toward your right shoulder for 20 seconds. Switch sides.', 18, 20, '3 mins', 'ph-eye', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Permission to Say ''No''', 'Every intentional ''no'' creates space for a meaningful ''yes'' to your wellbeing.', 'Identify one obligation, tab, or expectation you are carrying that isn''t truly mandatory. Give yourself permission to drop, postpone, or simplify it.', 19, 20, '5 mins', 'ph-shield-check', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Curiosity Rabbit Hole', 'Intrinsic curiosity refreshes mental energy and reminds you that learning is playful.', 'Spend 10 minutes reading or watching something purely out of curiosity—unrelated to work or productivity. How do whales sleep? How is glass made?', 20, 20, '10 mins', 'ph-compass', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Evening Worry Parking Lot', 'Creates a psychological boundary between daytime problem-solving and rest.', 'Write down any worry you have about tomorrow on a note. Fold it up and tell yourself: ''I have captured this; I will pick it up at 9 AM tomorrow.''', 21, 20, '4 mins', 'ph-archive-box', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Body Scan Check-In', 'Improves interoceptive awareness—your ability to read your body''s early stress signals.', 'Close your eyes and mentally scan from your forehead down to your toes. Notice where you are holding tightness without judging it, and breathe warmth into that area.', 22, 20, '5 mins', 'ph-person-simple-tai-chi', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Letter to Future You', 'Strengthens temporal connection with your future self, improving long-term decision-making.', 'Write a 3-sentence note of encouragement to yourself one month from today. What habit or mindset from this calendar do you want to keep alive?', 23, 20, '5 mins', 'ph-envelope-simple-open', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Mindfulness & Self-Help'), 'Celebrate Your Journey', 'Consciously marking endings consolidates positive memories and habit identity.', 'Look back at the doors you''ve opened and completed. Take a moment to acknowledge the time you carved out for your mental wellbeing. Leave your final reflection below!', 24, 30, '5 mins', 'ph-trophy', 'free', FALSE);
INSERT INTO calendars (title, category, description, icon, tier_required, status) VALUES ('Fitness Challenge', 'Fitness', 'Exercises and movement challenges for every level. Advanced sessions are Premium.', 'ph-barbell', 'free', 'active');
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Morning Mobility', 'Gentle movement wakes the body up.', 'Do 10 neck circles, 10 arm circles, 10 hip circles and 10 slow squats. Breathe deeply throughout.', 1, 20, '5 mins', 'ph-person-simple-tai-chi', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), '10-Minute Walk', 'Walking lifts mood and energy.', 'Walk briskly outdoors for 10 minutes. Leave your phone in your pocket and notice your surroundings.', 2, 20, '10 mins', 'ph-footprints', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Push-up Ladder', 'Builds upper-body strength anywhere.', 'Do 1 push-up, rest, 2 push-ups, rest, up to 6. Use your knees if needed and keep your back straight.', 3, 20, '8 mins', 'ph-barbell', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Squat Challenge', 'Strong legs support every movement.', 'Do 3 sets of 15 bodyweight squats with 45 seconds rest. Keep your chest up and knees over toes.', 4, 20, '8 mins', 'ph-arrow-fat-line-down', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Plank Hold', 'Core strength protects your back.', 'Hold a forearm plank for as long as you can with good form. Rest 1 minute and try again. Beat your time.', 5, 20, '5 mins', 'ph-timer', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Stairs Sprint', 'Short bursts boost cardio quickly.', 'Climb a flight of stairs at a fast pace 6 times, walking down to recover.', 6, 20, '10 mins', 'ph-stairs', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Interval Cardio Blast', 'Intervals raise fitness efficiently.', 'Alternate 40 seconds of jumping jacks, high knees and burpees with 20 seconds rest. 5 rounds.', 7, 40, '15 mins', 'ph-heartbeat', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Full-Body Strength Circuit', 'Balanced strength work builds resilience.', 'Do 4 rounds: 12 squats, 10 push-ups, 12 lunges per leg, 30 s plank. Rest 60 s between rounds.', 8, 40, '20 mins', 'ph-barbell', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Flexibility Flow', 'Stretching reduces stiffness and injury risk.', 'Hold each stretch for 30 seconds: hamstrings, quads, hip flexors, shoulders, chest, back. Do two rounds.', 9, 20, '12 mins', 'ph-flower-lotus', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Balance Practice', 'Balance keeps you stable as you move.', 'Stand on one leg for 45 seconds, eyes open, then 20 seconds eyes closed. Switch legs. Do 3 rounds.', 10, 20, '6 mins', 'ph-scales', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'HIIT Finisher', 'High intensity burns fat and builds stamina.', 'Do 8 rounds of 30 seconds all-out mountain climbers followed by 30 seconds of rest. Cool down with slow walking.', 11, 40, '15 mins', 'ph-fire', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Active Recovery & Review', 'Recovery is part of training.', 'Do a gentle walk and stretch, then write down what felt strongest this calendar and your next fitness goal.', 12, 20, '10 mins', 'ph-leaf', 'free', FALSE);
INSERT INTO calendars (title, category, description, icon, tier_required, status) VALUES ('Football Skills Calendar', 'Football', 'Drills, tactics and match-day practice to sharpen your football. Premium calendar.', 'ph-soccer-ball', 'premium', 'active');
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Ball Mastery Warm-up', 'Close control is the base of every football skill.', 'Using a ball, do 2 minutes each of sole rolls, inside-outside taps, and toe taps. Keep the ball within one step of your feet.', 1, 30, '10 mins', 'ph-soccer-ball', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Juggling Challenge', 'Juggling sharpens touch and coordination.', 'Try to keep the ball in the air with feet, thighs and shoulders. Beat your own record and note the number of touches.', 2, 30, '10 mins', 'ph-soccer-ball', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Passing Wall', 'Accurate passing wins matches.', 'Stand 5 metres from a wall. Play 30 passes with your right foot, 30 with your left, controlling each return in one touch.', 3, 30, '15 mins', 'ph-arrows-left-right', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Dribbling Slalom', 'Dribbling in tight spaces builds confidence under pressure.', 'Set up 6 markers (shoes, bottles) one metre apart. Dribble through and back 5 times, then repeat using only your weaker foot.', 4, 30, '15 mins', 'ph-path', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Shooting Accuracy', 'Placement beats power.', 'Take 15 shots at the corners of a goal or a marked target. Aim low into each corner and score your hits out of 15.', 5, 30, '15 mins', 'ph-target', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Watch & Learn: Tactics', 'Reading the game improves your decisions.', 'Watch 20 minutes of a match and track one player off the ball. Write down 3 positioning choices you would copy.', 6, 30, '20 mins', 'ph-television', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'First Touch Drill', 'A good first touch creates time and space.', 'Throw the ball up and cushion it with thigh, chest or foot so it stops dead within a metre. Repeat 20 times.', 7, 30, '10 mins', 'ph-hand-pointing', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Footwork Ladder', 'Quick feet improve agility and balance.', 'Draw a ladder with chalk or tape. Run through it with one foot in each box, then two feet in each box, then lateral steps. 6 rounds.', 8, 30, '10 mins', 'ph-footprints', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Small-Sided Game', 'Match situations make skills stick.', 'Organise a 3v3 or 5v5 kick-about with friends. Rotate teams and practise calling for the ball loudly.', 9, 30, '30 mins', 'ph-users-three', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Set-Piece Practice', 'Set pieces decide close games.', 'Practise 10 free kicks and 10 corners from a fixed spot. Aim at a target area and track how many reach it.', 10, 30, '20 mins', 'ph-flag', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Football Fitness Circuit', 'Match fitness is repeated sprinting.', 'Do 10 x 20 m sprints with 30 seconds rest, then 3 sets of 10 squat jumps. Finish with a gentle jog.', 11, 30, '20 mins', 'ph-lightning', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Reflect & Set a Goal', 'Goals keep your practice purposeful.', 'Write down your best moment from this calendar and one skill you will focus on next month.', 12, 30, '10 mins', 'ph-notebook', 'premium', FALSE);
INSERT INTO calendars (title, category, description, icon, tier_required, status) VALUES ('Nutrition & Cooking', 'Nutrition', 'Simple healthy recipes and habits. Coming soon.', 'ph-bowl-food', 'free', 'coming_soon');
